module Hecks
  module CLI
    module ProjectCli
      # The text of a launcher, as templates: each `{{name}}` is filled in by `render`.
      module Templates
        # The whole launcher: its header, the load path, the hand-offs, the entry and the ending.
        LAUNCHER = <<~RUBY.freeze
          #!/usr/bin/env ruby

          # {{name}}'s command line — GENERATED by {{program}}. Do not edit.
          #
          # A launcher, not a CLI: the commands, their arguments and their refusals are
          # projected from the bluebook beside it every time this runs, so a change
          # to the chapter shows up here without re-minting anything.
          #
          #   {{where}}                  every command, and every question
          #   {{where}} <command> --help    what it wants, and how it refuses

          {{encoding}}$LOAD_PATH.unshift File.expand_path("{{up}}lib", __dir__)
          {{handoff}}
          require "hecks"

          {{entry}}
          {{ending}}
        RUBY

        # An opted-in launcher's middle: usage answered from the projection, a boot only for a
        # line that runs a command.
        DESCRIBED_ENTRY = <<~'RUBY'.freeze
          # Usage is answered from the projected chapter alone: no adapter is bound and no
          # database is opened. Only a line that runs a command boots the domain,
          # and it boots from what the usage check already loaded.
          domain = {{boot}}
          program = "{{shown}}"
          described = begin
            Hecks.describe(domain)
          rescue StandardError => e
            abort "cannot open {{name}}: #{e.message.lines.first.strip}"
          end

          text, status, reason = Hecks::Adapters::Driving::CliRunner.usage(
            runtime: described, argv: ARGV, program: program
          )
          unless text
            runtime = begin
              {{started}}
            rescue StandardError => e
              abort "cannot open {{name}}: #{e.message.lines.first.strip}"
            end
            # A question the world lists under `streams`, given `--stream`, tails until interrupted.
            streamed = Hecks::Adapters::Driving::CliRunner.stream(runtime: runtime, argv: ARGV, program: program)
            exit streamed unless streamed.nil?
            text, status, reason = Hecks::Adapters::Driving::CliRunner.call(
              runtime: runtime, argv: ARGV, program: program
            )
          end
        RUBY

        # The middle every launcher had before opted-in ones answered usage alone.
        PLAIN_ENTRY = <<~'RUBY'.freeze
          runtime = begin
            Hecks.boot({{boot}}, install_driving: false)
          rescue StandardError => e
            abort "cannot open {{name}}: #{e.message.lines.first.strip}"
          end

          text, status = Hecks::Adapters::Driving::CliRunner.call(
            runtime: runtime, argv: ARGV, program: "{{shown}}"
          )
        RUBY

        # The lines that default listed commands to Memory.
        MEMORY_DEFAULT = <<~RUBY.freeze

          # These commands keep nothing worth a database, so they run on Memory unless told otherwise.
          # A person is at them: they wait for their result, say why when they are refused, and print
          # no record when they end well.
          MEMORY_COMMANDS = %w[{{commands}}].freeze
          ENV["HECKS_ENVIRONMENT"] ||= "memory" if MEMORY_COMMANDS.include?(ARGV.first.to_s.chomp("!"))
          ARGV << "--wait" if MEMORY_COMMANDS.include?(ARGV.first.to_s.chomp("!")) && !ARGV.include?("--wait")
        RUBY

        # The lines that hand the legacy commands to `Hecks::CLI`.
        LEGACY_HANDOFF = <<~RUBY.freeze

          # The names the gem has always shipped keep their positional forms.
          LEGACY = %w[{{commands}}].freeze
          if LEGACY.include?(ARGV.first)
            require "hecks/cli"
            exit Hecks::CLI.start(ARGV) unless Hecks::CLI.launcher_form?(ARGV)
          end
        RUBY

        # Fills a template's `{{name}}` placeholders.
        #
        # @param template [String] the template text
        # @param values [Hash{Symbol => String}] each placeholder's value
        # @return [String] the text with every placeholder replaced
        # @raise [KeyError] if the template names a placeholder `values` lacks
        def render(template, values)
          template.gsub(/\{\{(\w+)\}\}/) { values.fetch(Regexp.last_match(1).to_sym) }
        end
      end
    end
  end
end
